SELECT 'bankoffer_sodapeak','sodapeak','bank_offers','bank_offers','US','USD','https://sodapeak.com/home/','SodaPeak — Suplemento premium de energía y rendimiento (30 gomitas)','https://catalogo.s4accelerator.com/bank-offers/sodapeak.png',ARRAY['https://catalogo.s4accelerator.com/bank-offers/sodapeak.png']::TEXT[],80,289,'saude','Bank Offers · MVA',0,0,false,NULL,170,'[{"kind": "creatives", "label": "Creativos (carpeta de Drive)", "url": "https://drive.google.com/drive/folders/1wIMMlwFffoSpMfRnjDa1zW3K87kEM0C5"}]'::jsonb,'SodaPeak es una fórmula premium en gomitas para apoyar la energía, el rendimiento y la vitalidad. Oferta propia de MVA: promociona con tu enlace de afiliado.',true,false,NOW(),NOW(),NOW()
